esbmc_test_source:
contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 v) public {
        // ensure c has some balance by sending Ether to it
        // we can send value through fallback by simply transferring from this test contract
        uint256 cBalanceBefore = address(c).balance;
        bool reverted;
        c.withdraw(v); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        uint256 cBalanceAfter = address(c).balance;

        // General rule: withdraw succeeds iff v <= balance; on success balance decreases by v; on failure balance unchanged.
        assert(
            (reverted && cBalanceAfter == cBalanceBefore) ||
            (!reverted && v <= cBalanceBefore && cBalanceAfter == cBalanceBefore - v)
        );
    }

    receive() external payable {}
}

